/**
* Normalizes a URL string by adding https:// protocol if needed.
* This function determines the final URL that will be saved.
*
* Normalization rules:
* - Bare domains (wordpress.org, www.wordpress.org) → prepend https://
* - URLs with explicit protocols (http://, https://, mailto:, tel:, etc.) → keep as-is
* - Relative paths (/, ./, ../) → keep as-is
* - Hash links (#section) → keep as-is
*
* @param url - The URL to normalize
* @return An object containing the normalized URL and its type
*/
function normalizeUrl(url) {
	const trimmedUrl = url?.trim();
	if (!trimmedUrl) return {
		url: trimmedUrl,
		type: URL_TYPE
	};
	let type = URL_TYPE;
	const protocol = getProtocol(trimmedUrl) || "";
	if (protocol.includes("mailto")) type = MAILTO_TYPE;
	else if (protocol.includes("tel")) type = "tel";
	else if (trimmedUrl?.startsWith("#")) type = INTERNAL_TYPE;
	if (isHashLink(trimmedUrl) || isRelativePath(trimmedUrl) || trimmedUrl.startsWith("?") || protocol) return {
		url: trimmedUrl,
		type
	};
	return {
		url: prependHTTPS(trimmedUrl),
		type
	};
}
